function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function safeNumber(value, fallback = 0) {
 const n = Number(value);
 return Number.isFinite(n) ? n : fallback;
}

function makeEventId() {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 10);
 return `evt_${ts}_${rand}`;
}

function normalizeLevel(value, fallback = 'INFO') {
 const level = clean(value).toUpperCase();
 const allowed = ['DEBUG', 'INFO', 'WARN', 'ERROR'];
 return allowed.includes(level) ? level : fallback;
}

function normalizeStatus(value, fallback = 'success') {
 const status = clean(value).toLowerCase();
 const allowed = ['success', 'warning', 'error'];
 return allowed.includes(status) ? status : fallback;
}

const input = items[0]?.json || {};
const config = input.m8_config || {};
const defaults = config.defaults || {};

const rawEvent = input.event || input.m8_event_request?.event || input;

const trace = rawEvent.trace || input.trace || {};
const context = rawEvent.context || input.context || {};
const correlation = rawEvent.correlation || input.correlation || {};
const error = rawEvent.error || input.error || null;

const normalizedStatus = normalizeStatus(
 rawEvent.status,
 error ? 'error' : defaults.status || 'success'
);

const normalizedLevel = normalizeLevel(
 rawEvent.level,
 normalizedStatus === 'error' ? 'ERROR' : defaults.level || 'INFO'
);

const eventId =
 clean(rawEvent.event_id) ||
 clean(trace.event_id) ||
 makeEventId();

const normalizedEvent = {
 schema_version:
   input.schema_version ||
   config.contracts?.event_request_schema_version ||
   'dalia.m8.event_request.v1',

 event_id: eventId,

 timestamp:
   clean(rawEvent.timestamp) ||
   new Date().toISOString(),

 business_id:
   clean(context.business_id) ||
   clean(rawEvent.business_id) ||
   defaults.business_id ||
   'business_demo',

 environment:
   clean(context.environment) ||
   clean(rawEvent.environment) ||
   defaults.environment ||
   'demo',

 module:
   clean(rawEvent.module),

 event_type:
   clean(rawEvent.event_type),

 event_name:
   clean(rawEvent.event_name),

 status: normalizedStatus,
 level: normalizedLevel,

 trace: {
   event_id: eventId,
   conversation_id:
