     clean(rawEvent.conversation_id),

   session_id:
     clean(trace.session_id) ||
     clean(rawEvent.session_id),

   parent_event_id:
     clean(trace.parent_event_id) ||
     clean(correlation.parent_event_id) ||
     clean(rawEvent.parent_event_id)
 },

 context: {
   business_id:
     clean(context.business_id) ||
     clean(rawEvent.business_id) ||
     defaults.business_id ||
     'business_demo',

   environment:
