function isEmpty(value) {
 return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const event = input.m8_event || {};
const config = input.m8_config || {};

const errors = [];
const warnings = [];

const allowedStatuses = config.allowed_statuses || [
 'success',
 'warning',
 'error'
];

const allowedLevels = config.allowed_levels || [
 'DEBUG',
 'INFO',
 'WARN',
 'ERROR'
];

const allowedEventTypes = config.allowed_event_types || [];

if (isEmpty(event.event_id)) {
 errors.push('missing_event_id');
}

if (isEmpty(event.module)) {
 errors.push('missing_module');
}

if (isEmpty(event.event_type)) {
 errors.push('missing_event_type');
}

if (isEmpty(event.event_name)) {
 errors.push('missing_event_name');
}

if (!allowedStatuses.includes(event.status)) {
 errors.push('invalid_status');
}

if (!allowedLevels.includes(event.level)) {
 errors.push('invalid_level');
}

if (
 event.event_type &&
 allowedEventTypes.length > 0 &&
 !allowedEventTypes.includes(event.event_type)
) {
 warnings.push('event_type_not_in_allowed_list');
}

if (isEmpty(event.trace?.conversation_id)) {
 warnings.push('missing_conversation_id');
}

if (isEmpty(event.trace?.session_id)) {
 warnings.push('missing_session_id');
}

if (isEmpty(event.context?.user_id)) {
 warnings.push('missing_user_id');
}

if (event.status === 'error' && !event.error?.error_message) {
 warnings.push('error_event_without_error_message');
}

return [
 {
   json: {
     ...input,
     m8_validation: {
       valid: errors.length === 0,
       errors,
       warnings
     }
   }
 }
];

