const input = items[0]?.json || {};
const event = input.m8_event || {};

const eventId =
 clean(event.event_id) ||
 makeId('evt');

const conversationId = clean(event.trace?.conversation_id);
const sessionId = clean(event.trace?.session_id);
const userId = clean(event.context?.user_id);

const messageId = clean(event.correlation?.message_id);
const transactionId = clean(event.correlation?.transaction_id);
const handoffId = clean(event.correlation?.handoff_id);

const correlationId =
 clean(event.correlation?.correlation_id) ||
 conversationId ||
 sessionId ||
 eventId;

const traceId =
 clean(event.correlation?.trace_id) ||
 sessionId ||
 correlationId;

const parentEventId =
 clean(event.trace?.parent_event_id) ||
 clean(event.correlation?.parent_event_id);

const missing = [];

if (!conversationId) missing.push('conversation_id');
if (!sessionId) missing.push('session_id');
if (!userId) missing.push('user_id');

const correlationQuality =
 missing.length === 0
   ? 'complete'
   : missing.length <= 1
     ? 'partial'
     : 'weak';

const correlationContext = {
 event_id: eventId,

 conversation_id: conversationId,
 session_id: sessionId,
 user_id: userId,
 customer_id: clean(event.context?.customer_id),

 message_id: messageId,
 transaction_id: transactionId,
 handoff_id: handoffId,

 correlation_id: correlationId,
 trace_id: traceId,
 parent_event_id: parentEventId,

 channel: clean(event.context?.channel),

 quality: correlationQuality,
 missing_keys: missing
};

return [
 {
   json: {
     ...input,
     correlation_context: correlationContext
   }
 }
];

