}
if (!correlation.session_id) {
  warnings.push('missing_session_id');
}
if (!correlation.user_id) {
  warnings.push('missing_user_id');
}
if (event.event_type === 'commerce' && !correlation.transaction_id) {
  warnings.push('commerce_event_without_transaction_id');
}
if (event.event_type === 'handoff' && !correlation.handoff_id) {
