const memoryEvents = [
  'customer_memory_stored',
  'customer_memory_retrieved',
  'customer_memory_skipped',
  'customer_memory_error'
];
if (
  event.event_type === 'memory' &&
  memoryEvents.includes(event.event_name) &&
  !correlation.user_id
) {
  warnings.push('memory_event_without_user_id');
}

return [
  {
    json: {
      ...input,
      correlation_validation: {
        quality: correlation.quality || 'unknown',
        complete: warnings.length === 0,
        warnings
      }
    }
  }
